#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	UArenaScoreTracker* ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker is a plain UObject pointer, not a UPROPERTY, so the garbage collector does not see it as a live reference. The log shows the GC pass at 21:05.13 ('Collecting garbage: 412 objects purged') destroying UArenaScoreTracker shortly after it was created in BeginPlay. 14 seconds later, OnGoalScored() calls ScoreTracker->AddPoints(TeamIndex, 1) through the now-dangling pointer and hits EXCEPTION_ACCESS_VIOLATION (UArenaScoreTracker::AddPoints, ArenaScoreTracker.cpp:18, called from ArenaGameMode.cpp OnGoalScored). Fix: mark ScoreTracker with UPROPERTY() in ArenaGameMode.h so the GC keeps it alive.",
  "no_colors_cause": "DefaultGame.ini has bCookAll=False and only cooks /Game/Maps/Arena plus DirectoriesToAlwaysCook /Game/Data/Effects. The palette /Game/Data/Palettes/DA_Primary is not referenced by the map and is not in an always-cook directory, so it is not cooked into the Shipping pak. At runtime LoadObject<UArenaPalette>('/Game/Data/Palettes/DA_Primary.DA_Primary') in BeginPlay fails (log lines 4-6: 'Couldn't find file for package ... DA_Primary' / 'Palette is null, using fallback gray'), the HUD falls back to gray and the arena renders without colors. Fix: add +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to DefaultGame.ini."
}
